def qmark(cx, cy, s, c):
    return [arc(cx, cy, round(4 * s), round(8 * s), 180, 420, c, 8), R(cx - round(2 * s), cy + round(5 * s), round(4 * s), round(5 * s), c), O(cx, cy + round(14 * s), round(2 * s), round(2 * s), c)]


def cup(x, h, c):
    return P([(x - h // 3, 150 - h), (x + h // 3, 150 - h), (x + h // 4, 150), (x - h // 4, 150)], c)


def bulb(cx, c):
    return [O(cx, 84, 20, 22, c, 14), R(cx - 9, 104, 18, 6, GS), R(cx - 7, 110, 14, 5, GY)]


